<header>Public<span>Service</span> Portal</header>
<main>
<div class="panel" id="panel">
<h1>Create Account</h1>
<p class="subtitle">Fill in the details below to register.</p>
<form id="regForm" novalidate autocomplete="on" aria-label="Registration form">
<div class="grid">
<div class="field">
<label for="username">Username <span class="sr-only">(required)</span></label>
<input type="text" id="username" name="username" required autocomplete="username" minlength="3" maxlength="30" aria-describedby="usernameErr">
<div class="error-msg" id="usernameErr" role="alert" aria-live="polite"></div>
</div>
<div class="field">
<label for="email">Email Address <span class="sr-only">(required)</span></label>
<input type="email" id="email" name="email" required autocomplete="email" aria-describedby="emailErr">
<div class="error-msg" id="emailErr" role="alert" aria-live="polite"></div>
</div>
</div>
<div class="grid">
<div class="field">
<label for="dob">Date of Birth</label>
<input type="date" id="dob" name="dob" autocomplete="bday">
<div class="error-msg" id="dobErr" role="alert" aria-live="polite"></div>
</div>
<div class="field">
<label for="password">Password <span class="sr-only">(required)</span></label>
<div class="input-wrap">
<input type="password" id="password" name="password" required autocomplete="new-password" minlength="8" aria-describedby="passwordErr">
<button type="button" class="toggle-pw" data-target="password" aria-label="Show password" tabindex="0">Show</button>
</div>
<div class="error-msg" id="passwordErr" role="alert" aria-live="polite"></div>
</div>
</div>
<div class="field">
<label for="confirmPassword">Confirm Password <span class="sr-only">(required)</span></label>
<div class="input-wrap">
<input type="password" id="confirmPassword" name="confirmPassword" required autocomplete="new-password" aria-describedby="confirmErr">
<button type="button" class="toggle-pw" data-target="confirmPassword" aria-label="Show password" tabindex="0">Show</button>
</div>
<div class="error-msg" id="confirmErr" role="alert" aria-live="polite"></div>
</div>
<div class="checkbox-field">
<input type="checkbox" id="terms" name="terms" required>
<label for="terms">I accept the <a href="#" onclick="event.preventDefault()">Terms of Service</a></label>
</div>
<div class="error-msg" id="termsErr" role="alert" aria-live="polite" style="margin-top:-1rem;margin-bottom:1rem"></div>
<button type="submit" class="submit-btn" id="submitBtn">Register</button>
</form>
<div class="success-msg" id="successMsg">
<h2>Registration Successful!</h2>
<p>Your account has been created. You may now log in.</p>
</div>
</div>
