<script>
(function(){
const STORAGE_KEY='registered_users';
const form=document.getElementById('regForm');
const fields={
username:{el:document.getElementById('username'),err:document.getElementById('usernameErr')},
email:{el:document.getElementById('email'),err:document.getElementById('emailErr')},
dob:{el:document.getElementById('dob'),err:document.getElementById('dobErr')},
password:{el:document.getElementById('password'),err:document.getElementById('passwordErr')},
confirmPassword:{el:document.getElementById('confirmPassword'),err:document.getElementById('confirmErr')}
};
const termsEl=document.getElementById('terms');
const termsErr=document.getElementById('termsErr');
const submitBtn=document.getElementById('submitBtn');
const successMsg=document.getElementById('successMsg');

function getRegistered(){
try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');}catch(e){return[];}
}
function saveRegistered(users){localStorage.setItem(STORAGE_KEY,JSON.stringify(users));}

function validateField(name){
const f=fields[name];if(!f)return true;
let msg='',valid=true;
const v=f.el.value.trim();
switch(name){
case 'username':
if(!v){msg='Username is required.';valid=false;}
else if(v.length<3)msg='Must be at least 3 characters.';
else if(!/^[a-zA-Z0-9_]+$/.test(v))msg='Only letters, numbers, and underscores allowed.';
else if(getRegistered().some(u=>u.username===v.toLowerCase()))msg='Username already taken.';
break;
case 'email':
if(!v){msg='Email address is required.';valid=false;}
else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))msg='Enter a valid email address.';
else if(getRegistered().some(u=>u.email===v.toLowerCase()))msg='This email is already registered.';
break;
case 'dob':
if(v){
const d=new Date(v);
const now=new Date();
const age=(now-d)/(365.25*24*60*60*1000);
if(age<0||age>150)msg='Please enter a valid date of birth.';
}
break;
case 'password':
if(!v){msg='Password is required.';valid=false;}
else if(v.length<8)msg='Must be at least 8 characters.';
else if(!/[A-Z]/.test(v))msg='Include at least one uppercase letter.';
else if(!/[a-z]/.test(v))msg='Include at least one lowercase letter.';
else if(!/\d/.test(v))msg='Include at least one number.';
break;
case 'confirmPassword':
if(!v){msg='Please confirm your password.';valid=false;}
else if(v!==f.el.form.password.value)msg='Passwords do not match.';
break;
}
f.err.textContent=msg;
f.el.classList.toggle('invalid',!valid&&!!v);
f.el.classList.toggle('valid',valid&&!!v);
return valid;
}

Object.keys(fields).forEach(function(n){
var f=fields[n];
f.el.addEventListener('blur',function(){validateField(n);});
f.el.addEventListener('input',function(){
if(f.el.classList.contains('invalid'))validateField(n);
});
});

termsEl.addEventListener('change',function(){
if(!this.checked)termsErr.textContent='You must accept the Terms of Service.';
else termsErr.textContent='';
});

document.querySelectorAll('.toggle-pw').forEach(function(btn){
btn.addEventListener('click',function(){
var inp=document.getElementById(this.getAttribute('data-target'));
if(inp.type==='password'){inp.type='text';this.textContent='Hide';this.setAttribute('aria-label','Hide password');}
else{inp.type='password';this.textContent='Show';this.setAttribute('aria-label','Show password');}
});
});

form.addEventListener('submit',function(e){
e.preventDefault();
var allValid=true;
Object.keys(fields).forEach(function(n){if(!validateField(n))allValid=false;});
if(!termsEl.checked){termsErr.textContent='You must accept the Terms of Service.';allValid=false;}
if(!allValid){submitBtn.focus();return;}
var users=getRegistered();
users.push({username:fields.username.el.value.trim().toLowerCase(),email:fields.email.el.value.trim().toLowerCase()});
saveRegistered(users);
form.style.display='none';
successMsg.style.display='block';
});
})();
</script>
